\usetikzlibrary{calc,angles,quotes,arrows.meta}
\begin{tikzpicture}[x=1cm,y=1cm,draw=black,text=black,line width=0.8pt,font=\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\coordinate (E) at (0,0);
\coordinate (F) at (2.5,0);
\coordinate (A) at (0.8,4.4);
\coordinate (C) at ($(E)!0.590909!(A)$);
\coordinate (D) at ($(F)!0.590909!(A)$);
\coordinate (B) at ($(D)+(E)-(F)$);
\draw (E)--(A)--(F)--cycle;
\draw (B)--(D) (B)--(E);
\foreach \P/\Q in {E/B,F/D}{\draw[line width=0.4pt,-{Stealth[length=1.8mm,width=1.2mm]}] ($(\P)!0.46!(\Q)$)--($(\P)!0.54!(\Q)$);}
\foreach \P/\Q in {B/D,E/F}{\draw[line width=0.4pt,-{Stealth[length=1.6mm,width=1.1mm]}] ($(\P)!0.45!(\Q)$)--($(\P)!0.50!(\Q)$);\draw[line width=0.4pt,-{Stealth[length=1.6mm,width=1.1mm]}] ($(\P)!0.50!(\Q)$)--($(\P)!0.55!(\Q)$);}
\pic[draw,line width=0.4pt,angle radius=5mm,angle eccentricity=1.45,"$80^{\circ}$"] {angle=D--C--A};
\pic[draw,line width=0.4pt,angle radius=5mm,angle eccentricity=1.5,"$70^{\circ}$"] {angle=D--F--E};
\node[above=2pt] at (A) {$A$};
\node[left=2pt] at (B) {$B$};
\node[above left=2pt] at (C) {$C$};
\node[right=2pt] at (D) {$D$};
\node[below left=2pt] at (E) {$E$};
\node[below right=2pt] at (F) {$F$};
\end{tikzpicture}

